def main() -> int:
    doc_path = REPO_ROOT / "docs" / "functions.md"
    documented = get_documented_entries(doc_path)
    if not documented:
        print(f"error: no documented entries found in {doc_path}")
        return 1

    total_missing = []
    # Audit src/mythosmini
    for path in (REPO_ROOT / "src" / "mythosmini").rglob("*.py"):
        total_missing.extend(audit_file(path, documented))

    # Audit individual entry points
    for name in ["train.py", "ralph.py", "pyaot.py"]:
        path = REPO_ROOT / name
        if path.exists():
            total_missing.extend(audit_file(path, documented))

    if total_missing:
        print("error: missing documentation in docs/functions.md for:")
        for m in sorted(total_missing):
            print(f"  {m}")
        return 1

